diamond.cpp
```cpp
#include "diamond.h"

#include <string>

namespace diamond {

std::string rows(char letter) {
  const int height = letter - 'A';
  const int width = height * 2 + 1;
  std::string result;

  for (int row = 0; row <= height * 2; ++row) {
    const int distance_from_top = row <= height ? row : height * 2 - row;
    const char current_letter = static_cast<char>('A' + distance_from_top);
    const int leading_spaces = height - distance_from_top;

    result.append(leading_spaces, ' ');
    result.push_back(current_letter);

    if (distance_from_top > 0) {
      result.append(distance_from_top * 2 - 1, ' ');
      result.push_back(current_letter);
    }

    result.append(leading_spaces, ' ');
    result.push_back('\n');
  }

  return result;
}

}  // namespace diamond
```

